SELECT data_month, CASE MONTH(data_month) WHEN 1 THEN 'January' WHEN 2 THEN 'February' WHEN 3 THEN 'March' ELSE 'Other' END AS month_name, COUNT(*) AS trips, SUM(total_amount) AS revenue_usd, AVG(CASE WHEN total_amount IS NOT NULL AND total_amount > 0 THEN total_amount END) AS avg_total_usd, AVG(CASE WHEN fare_amount IS NOT NULL AND fare_amount > 0 THEN fare_amount END) AS avg_fare_usd, AVG(CASE WHEN trip_distance_miles IS NOT NULL AND trip_distance_miles > 0 THEN trip_distance_miles END) AS avg_distance_miles, AVG(CASE WHEN trip_duration_minutes IS NOT NULL AND trip_duration_minutes > 0 THEN trip_duration_minutes END) AS avg_duration_minutes FROM tlc.taxi.yellow_trips WHERE data_month IN (DATE '2026-01-01', DATE '2026-02-01', DATE '2026-03-01') AND data_month IS NOT NULL GROUP BY data_month ORDER BY data_month
